"""Offline evidence view. Source/model text is never inserted as HTML."""
import json
import re
from .observatory import check_bundle, check_review_events


def render(bundle, reviews=None):
    check_bundle(bundle)
    events = check_review_events(bundle, reviews) if reviews is not None else []
    payload = json.dumps(bundle, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    review_payload = json.dumps(events, ensure_ascii=True, allow_nan=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    return re.sub(r"__BUNDLE__|__REVIEWS__", lambda match: payload if match[0] == "__BUNDLE__" else review_payload, TEMPLATE)


TEMPLATE = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'none'; base-uri 'none'; form-action 'none'">
<title>Lost in Switzerland — Evidence desk</title>
<style>
:root{--paper:#f5f4ef;--ink:#202c2b;--muted:#64716d;--line:#d9ddd3;--green:#d9e7b3;--purple:#e6def2;--orange:#efd9bd}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select,textarea{font:inherit;color:inherit}button,select,input,textarea{border:1px solid var(--line);background:#fff;border-radius:5px;padding:9px 12px}button{cursor:pointer}button:hover{background:var(--green)}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #7774c0;outline-offset:2px}a{color:inherit;text-underline-offset:4px}header{padding:30px 4vw 22px;border-bottom:1px solid var(--line)}.eyebrow{font-size:11px;letter-spacing:.15em;text-transform:uppercase;color:var(--muted)}h1{font-size:clamp(30px,4vw,52px);letter-spacing:-.045em;line-height:1.06;margin:10px 0}header p{margin:8px 0;color:var(--muted)}.topline{display:flex;justify-content:space-between;gap:20px;align-items:center}.badge{display:inline-block;font-size:11px;text-transform:uppercase;letter-spacing:.06em;padding:4px 8px;background:var(--purple)}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);min-height:65vh}aside{border-right:1px solid var(--line);padding:22px}aside button{display:block;width:100%;margin:9px 0;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--line);border-radius:0;padding:15px 8px}aside button.active{background:var(--green)}aside small{display:block;color:var(--muted)}main{padding:24px 3vw;min-width:0}.metrics{display:flex;gap:25px;flex-wrap:wrap;margin:12px 0 20px}.metrics b{font-size:25px}.metrics span{font-size:12px;color:var(--muted)}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}.notice{padding:12px 16px;background:#eaece3;border-left:3px solid #869563;margin:15px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.doc{min-width:0}.dochead{border-bottom:1px solid var(--line);padding-bottom:12px;margin-bottom:18px}.dochead h3{font-size:18px;margin:8px 0}.dochead small{display:block;color:var(--muted);word-break:break-word}.block{white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0}.block.heading{font-size:19px;font-weight:600;margin-top:24px}.block.list_item{border-left:2px solid var(--line);padding-left:14px}.block.table_row{font-family:ui-monospace,monospace;border-bottom:1px solid var(--line);padding:8px 0}.locator{display:block;font-size:10px;color:var(--muted)}mark{background:var(--orange);color:inherit;padding:1px 0}.candidate{border:1px solid var(--line);padding:17px;margin:10px 0;background:#fafaf7}.candidate.selected{border-color:#828d66;background:#f0f3e5}.candidate button{margin:8px 8px 0 0}.candidate p{margin:6px 0}.candidate small{color:var(--muted)}details{margin:18px 0;border-top:1px solid var(--line);padding-top:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.review{display:grid;gap:9px;margin-top:12px}.review label{display:grid;gap:4px}.empty{padding:40px 0;max-width:650px}.empty h2{font-size:28px;letter-spacing:-.025em}footer{border-top:1px solid var(--line);padding:16px 4vw;color:var(--muted);font-size:12px}.quiet{color:var(--muted)}@media(max-width:850px){.layout{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}aside button{padding:8px}.grid{grid-template-columns:1fr}header{padding:22px}main{padding:20px}.topline{align-items:flex-start}}
</style></head><body>
<header><div class="topline"><div class="eyebrow">Stadt Zürich · Real-world observatory</div><span class="badge">Private evidence desk</span></div><h1>Lost in Switzerland</h1><p>Same city. Different language. Same information?</p></header>
<div class="layout"><aside><div class="eyebrow">Captured sources</div><div id="metrics" class="metrics"></div><label for="search">Find a page</label><input id="search" type="search" placeholder="Title or URL" style="width:100%;margin-top:6px"><div id="nav"></div></aside><main id="content"></main></div>
<footer>German content is legally binding; translations are assistance. Candidate differences need human verification. WATCH is not implemented. Captured text is for personal use; publication requires rights review. <a href="https://www.stadt-zuerich.ch/de/service/rechtliche-hinweise.html" target="_blank" rel="noopener noreferrer">City terms</a></footer>
<script type="application/json" id="evidence">__BUNDLE__</script>
<script>
'use strict';
const bundle=JSON.parse(document.getElementById('evidence').textContent);
const reviewEvents=__REVIEWS__;
const entries=[...bundle.pairs.map(p=>({type:'pair',id:p.pair_id,p,title:p.en.title||p.de.title})),...bundle.unpaired.map(d=>({type:'unpaired',id:d.capture_id,d,title:d.title||d.url}))];
let current=entries[0],selected=null,filter='all';const drafts=new Map();
const $=id=>document.getElementById(id);
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function add(parent,tag,text,cls){const n=el(tag,text,cls);parent.append(n);return n}
function link(parent,text,url){const n=add(parent,'a',text);n.href=url;n.target='_blank';n.rel='noopener noreferrer';return n}
function button(parent,text,fn){const n=add(parent,'button',text);n.type='button';n.addEventListener('click',fn);return n}
function download(value,name){const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function navigation(){const nav=$('nav');nav.replaceChildren();const query=$('search').value.toLowerCase();for(const entry of entries){const url=entry.type==='pair'?entry.p.en.url:entry.d.url;if(!(entry.title+' '+url).toLowerCase().includes(query))continue;const b=button(nav,entry.title,()=>{current=entry;selected=null;filter='all';navigation();show()});if(current===entry)b.className='active';add(b,'small',entry.type==='pair'?'DE ↔ EN · correspondence accepted':'Unpaired · '+(entry.d.language||'language unknown'))}}
function summary(){const m=$('metrics');m.replaceChildren();for(const [n,label] of [[bundle.discovery.captured,'pages'],[bundle.pairs.length,'pairs'],[bundle.model_calls,'model calls']]){const d=add(m,'div');add(d,'b',String(n));add(d,'br');add(d,'span',label)}}
function documentView(parent,doc,language,locations){const panel=add(parent,'section',undefined,'doc');panel.lang=doc.language||language;const head=add(panel,'div',undefined,'dochead');add(head,'div',(doc.language||'').startsWith('de')?'Deutsch · legally authoritative':(doc.language||'').startsWith('en')?'English · translation':'Observed source · '+(doc.language||'language unknown'),'eyebrow');add(head,'h3',doc.title);link(head,'Open original source ↗',doc.url);add(head,'small','Captured '+doc.retrieved_at_utc);add(head,'small',doc.extraction_version+' · '+doc.text_sha256.slice(0,12));for(const b of doc.blocks){const p=add(panel,'div',undefined,'block '+b.kind);p.id=language+'-'+b.id;const ranges=locations.map(s=>({start:Math.max(s.start,b.start),end:Math.min(s.end,b.end)})).filter(s=>s.end>s.start).sort((a,b)=>a.start-b.start);let pos=b.start;for(const s of ranges){if(s.start<pos)continue;p.append(document.createTextNode(doc.text.slice(pos,s.start)));add(p,'mark',doc.text.slice(s.start,s.end));pos=s.end}p.append(document.createTextNode(doc.text.slice(pos,b.end)));if(selected)add(p,'small',b.id+' · HTML line '+b.source_line,'locator')}if(!doc.blocks.length)add(panel,'p','Extraction unresolved: '+doc.reason,'notice')}
function provenance(parent,p){const detail=add(parent,'details');add(detail,'summary','Evidence & method provenance');add(detail,'pre',JSON.stringify({pair_id:p.pair_id,revision:p.revision,pairing_review:p.pairing_review,analysis_status:p.analysis.status,finish_reason:p.analysis.finish_reason,provenance:p.analysis.provenance,diagnostics:p.analysis.diagnostics},null,2));}
function show(){const main=$('content');main.replaceChildren();if(!current){add(main,'h2','No captures in this bundle');return}if(current.type==='unpaired'){add(main,'h2',current.title);add(main,'p','Observed source. No accepted German–English correspondence, so no semantic analysis.','notice');const grid=add(main,'div',undefined,'grid');documentView(grid,current.d,(current.d.language||'').startsWith('en')?'en':'de',[]);return}
const p=current.p,a=p.analysis;add(main,'div','Paired source evidence','eyebrow');add(main,'h2',current.title);add(main,'p','Source correspondence accepted by '+p.pairing_review.reviewer+' ('+p.pairing_review.reviewer_type+'). This establishes a comparison, not semantic equivalence.','quiet');
if(a.status==='not_run')add(main,'p','Analysis has not run. You can inspect the real captured documents below.','notice');else if(a.status!=='ok')add(main,'p','Analysis unresolved: '+(a.reason||a.status)+'. Missing output is not equivalence.','notice');else if(!a.candidates.length)add(main,'p','The method returned no candidates. This does not establish equivalent information.','notice');else add(main,'p',a.candidates.length+' model-generated candidates. Located excerpts support inspection; they do not confirm the model’s interpretation. Confidence is unavailable.','notice');
if(a.finish_reason==='length')add(main,'p','Generation reached its output limit. Treat coverage as incomplete.','notice');
const toolbar=add(main,'div',undefined,'toolbar');const label=add(toolbar,'label','Review state ');const select=add(label,'select');for(const [value,text] of [['all','All candidates'],['candidate','Candidates'],['unresolved','Unresolved'],['human_confirmed','Confirmed / confirmation drafts'],['rejected','Rejected / rejection drafts']]){const option=add(select,'option',text);option.value=value;option.selected=value===filter}select.onchange=()=>{filter=select.value;show()};button(toolbar,'Export evidence bundle',()=>download(bundle,'zurich-evidence-bundle.json'));button(toolbar,'Export review drafts',()=>download({schema:'lost-in-switzerland/review-drafts/v1',bundle_digest:bundle.bundle_digest,drafts:[...drafts.values()]},'zurich-review-drafts.json'));
const list=add(main,'section');list.setAttribute('aria-label','Difference candidates');for(const c of a.candidates){const state=drafts.get(c.candidate_id)?.state||reviewEvents.filter(e=>e.candidate_id===c.candidate_id).at(-1)?.state||c.review_state;if(filter!=='all'&&state!==filter)continue;const card=add(list,'article',undefined,'candidate'+(selected===c.candidate_id?' selected':''));add(card,'span',c.kind+' · '+state+(drafts.has(c.candidate_id)?' (draft)':''),'badge');add(card,'p','English: '+(c.excerpt_en||'[model claims absence]'));add(card,'p','Deutsch: '+(c.excerpt_de||'[model claims absence]'));add(card,'small','Model severity: '+(c.severity??'unavailable')+'/5 · confidence: unavailable · '+c.validation);if(c.issues.length)add(card,'p','Unresolved: '+c.issues.join(', '),'quiet');button(card,'Inspect evidence',()=>{selected=c.candidate_id;show();$('comparison').scrollIntoView({behavior:'smooth',block:'start'})});button(card,'Review',()=>{selected=c.candidate_id;show()});
if(selected===c.candidate_id){const review=add(card,'div',undefined,'review');const previous=drafts.get(c.candidate_id);const who=add(add(review,'label','Reviewer'),'input');who.value=previous?.reviewer||'';who.placeholder='Your name';const note=add(add(review,'label','Reason / context'),'textarea');note.value=previous?.rationale||'';const choices=add(review,'div');for(const [state,text] of [['human_confirmed','Confirm'],['rejected','Reject'],['unresolved','Leave unresolved']]){const b=button(choices,text,()=>{if(!who.value.trim()||!note.value.trim()){who.reportValidity();note.reportValidity();return}drafts.set(c.candidate_id,{pair_id:p.pair_id,pair_revision:p.revision,candidate_id:c.candidate_id,state,reviewer:who.value.trim(),rationale:note.value.trim(),reviewed_at_utc:new Date().toISOString()});show()});b.disabled=state==='human_confirmed'&&(c.validation!=='evidence_located'||a.finish_reason==='length')}who.required=true;note.required=true;add(review,'small','Drafts stay in this browser tab. Export them before closing; no server saves or publishes them.')}
}
const comparison=add(main,'section');comparison.id='comparison';const grid=add(comparison,'div',undefined,'grid');const c=a.candidates.find(c=>c.candidate_id===selected);documentView(grid,p.de,'de',c?.de.locations||[]);documentView(grid,p.en,'en',c?.en.locations||[]);provenance(main,p);const details=add(main,'details');add(details,'summary','Discovery limits & failures');add(details,'pre',JSON.stringify(bundle.discovery,null,2));}
$('search').addEventListener('input',navigation);summary();navigation();show();
</script></body></html>'''
